import{_ as e,o as s,c as i,a3 as t}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"CMake","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"CMake | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/integrations/cmake"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/integrations/cmake"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/integrations/cmake"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/integrations/cmake"}]]},"headers":[],"relativePath":"xclang/integrations/cmake.md","filePath":"en/xclang/integrations/cmake.md","lastUpdated":1791227177000}'),n={name:"xclang/integrations/cmake.md"};function l(h,a,o,c,d,p){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="cmake" tabindex="-1">CMake <a class="header-anchor" href="#cmake" aria-label="Permalink to &quot;CMake&quot;">​</a></h1><p>xclang&#39;s CMake package makes the toolchain a build&#39;s compiler, for the host or another target, and gives the build libc++&#39;s <code>std</code> and <code>std.compat</code> modules as a library to link: <code>import std</code> without CMake&#39;s experimental <code>CMAKE_EXPERIMENTAL_CXX_IMPORT_STD</code>.</p><p>It needs CMake 3.28 and Ninja 1.11 or later, the first that build C++20 modules, and the Ninja or Ninja Multi-Config generator: CMake builds modules with no other generator for these targets. The package is in every toolchain archive from 23.1.2.6 on, in <code>lib/cmake/xclang</code> (and so in the conda package), and in this repository, <code>packages/cmake/</code>, at every tag. Every variable and function is listed in the <a href="./../reference/cmake-api">CMake API</a>.</p><h2 id="with-xclang-installed" tabindex="-1">With xclang installed <a class="header-anchor" href="#with-xclang-installed" aria-label="Permalink to &quot;With xclang installed&quot;">​</a></h2><p>pixi puts xclang&#39;s <code>bin/</code> first in <code>PATH</code>; for an unpacked archive, do the same or use the toolchain file below. CMake does not pick clang by itself:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_C_COMPILER=clang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_CXX_COMPILER=clang++</span></span></code></pre></div><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cmake_minimum_required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 3.28)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(app LANGUAGES CXX)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">find_package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(xclang REQUIRED CONFIG)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_executable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(app main.cpp)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(app </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xclang::std)</span></span></code></pre></div><p><code>find_package(xclang)</code> finds the package through <code>PATH</code> (<code>&lt;xclang&gt;/bin</code> gives <code>&lt;xclang&gt;/lib/cmake/xclang</code>), or <code>-Dxclang_ROOT=&lt;xclang&gt;</code>. It comes after <code>project()</code>, whose C++ compiler must be xclang&#39;s.</p><p>The toolchain file sets the compilers and binary tools (<code>llvm-ar</code>, <code>llvm-ranlib</code>, ...) of a tree and the package&#39;s location at once, without <code>PATH</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toolchain</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">xclan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/lib/cmake/xclang/toolchain.cmake</span></span></code></pre></div><p>A ready project is in <a href="https://github.com/clice-io/xclang/tree/main/examples/cmake" target="_blank" rel="noreferrer">examples/cmake</a>: the <a href="./../guide/quick-start">quick start</a> builds it.</p><h2 id="without-xclang-installed" tabindex="-1">Without xclang installed <a class="header-anchor" href="#without-xclang-installed" aria-label="Permalink to &quot;Without xclang installed&quot;">​</a></h2><p>Before <code>project()</code>, FetchContent fetches this repository at the release&#39;s tag, and <code>packages/cmake/xclang.cmake</code> downloads that release&#39;s toolchain for the host and makes it the build&#39;s:</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cmake_minimum_required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 3.28)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(XCLANG_VERSION 23.1.2.6)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(FetchContent)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_Declare(xclang</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_REPOSITORY https://github.com/clice-io/xclang</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_TAG </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${XCLANG_VERSION}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_MakeAvailable(xclang)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${xclang_SOURCE_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/packages/cmake/xclang.cmake)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(app LANGUAGES CXX)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">find_package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(xclang REQUIRED CONFIG)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_executable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(app main.cpp)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(app </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xclang::std)</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The tag holds <code>packages/cmake/</code> from 23.1.2.6 on. <code>GIT_TAG</code> may also name a later commit, with <code>XCLANG_VERSION</code> the release whose toolchain it downloads: an earlier one works too.</p><p><code>xclang.cmake</code> downloads the release&#39;s <code>SHA256SUMS</code> and <code>xclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code>, checks the archive against its line there, unpacks it into the user&#39;s cache, once per version and host, and sets <code>CMAKE_TOOLCHAIN_FILE</code> to its toolchain file. Another build tree of the same release and host finds the toolchain in the cache and downloads nothing but the checkout. The archive is as trustworthy as the release&#39;s <code>SHA256SUMS</code>: both come from the GitHub release, and releases are not yet immutable (<a href="./../reference/releases#checking-a-download">releases</a>).</p><p><code>XCLANG_CACHE_DIR</code> moves the cache, <code>XCLANG_ROOT</code> uses an unpacked xclang instead of downloading one, <code>XCLANG_URL</code> names a mirror. <code>xclang.cmake</code> stops if the build has a toolchain file of its own already (vcpkg&#39;s, say); vcpkg chain-loads an installed xclang&#39;s (<code>VCPKG_CHAINLOAD_TOOLCHAIN_FILE</code>) instead.</p><h2 id="other-targets" tabindex="-1">Other targets <a class="header-anchor" href="#other-targets" aria-label="Permalink to &quot;Other targets&quot;">​</a></h2><p><code>XCLANG_TARGET</code> builds for another target of the tree, with either way of getting it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-arm64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toolchain</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">xclan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/lib/cmake/xclang/toolchain.cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -DXCLANG_TARGET=aarch64-w64-mingw32</span></span></code></pre></div><ul><li>Linux and Windows targets build on every host. macOS targets build on macOS only (Xcode&#39;s SDK); the other macOS architecture is <code>CMAKE_OSX_ARCHITECTURES</code> to CMake, not cross-compiling, and x86_64 programs run on arm64 macOS through Rosetta.</li><li>CMake looks for the libraries, headers and packages of another target in that target&#39;s directory only (<code>CMAKE_SYSROOT</code>, <code>CMAKE_FIND_ROOT_PATH_MODE_*</code> <code>ONLY</code>): a dependency built for the target is named by <code>&lt;Package&gt;_DIR</code>, or its prefix added to <code>CMAKE_FIND_ROOT_PATH</code>. A library found on the build machine would be the wrong architecture or OS, and the link would fail late or, worse, succeed against the wrong headers.</li><li><code>xclang::std</code> is built for the target too.</li><li>Tests built for another target run on a machine of that target, not on the build machine.</li></ul><h2 id="import-std" tabindex="-1">import std <a class="header-anchor" href="#import-std" aria-label="Permalink to &quot;import std&quot;">​</a></h2><p><code>xclang::std</code> is a static library of libc++&#39;s <code>std</code> and <code>std.compat</code> modules, one target for both, compiled from the sources the compiler&#39;s module manifest names (<code>clang++ -print-library-module-manifest-path</code>) for the build&#39;s target. It is built only when something links it.</p><p>clang refuses a module file built with other language options than its importer&#39;s: <code>-std</code>, GNU extensions, <code>-fno-exceptions</code>, <code>-fno-rtti</code>, ...; macros, include paths and optimization may differ (<a href="./../features/modules">C++20 modules</a> says why). So:</p><ul><li><p><code>xclang::std</code> is built with the settings of the directory that called <code>find_package(xclang)</code>, as they are at the end of its <code>CMakeLists.txt</code>: <code>CMAKE_CXX_STANDARD</code>, <code>CMAKE_CXX_EXTENSIONS</code>, <code>CMAKE_CXX_FLAGS</code>, <code>add_compile_options()</code>. Importers that take theirs from the same place match it; set them project-wide, not per target.</p></li><li><p>It asks its importers for its standard, C++23 or the <code>CMAKE_CXX_STANDARD</code> it was built with if that is 20 or later. A target asking for a newer one (<code>cxx_std_26</code>) gets <code>C++26 was disabled in precompiled file</code>.</p></li><li><p>A target with other language options links a std of its own, whose <code>PUBLIC</code> options reach its importers:</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">xclang_add_std(std_noexcept)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_compile_options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(std_noexcept </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PUBLIC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -fno-exceptions)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(kernel </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> std_noexcept)</span></span></code></pre></div></li></ul><p>A program&#39;s own modules are CMake&#39;s <code>FILE_SET CXX_MODULES</code>, scanned by clang-scan-deps; <code>cmake_minimum_required(VERSION 3.28)</code> or later turns on the scanning of C++20 targets (CMP0155).</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_library</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(geometry STATIC)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(geometry </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PUBLIC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FILE_SET CXX_MODULES FILES geometry.cppm geometry-shapes.cppm)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(geometry </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PUBLIC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xclang::std)</span></span></code></pre></div><p>ccache never caches a module interface, and before 4.14 it serves an importer&#39;s stale object after the interface changed; see <a href="./../features/modules#build-caches-and-modules">C++20 modules</a> before putting it in front of the compiler.</p><h2 id="debug-symbols" tabindex="-1">Debug symbols <a class="header-anchor" href="#debug-symbols" aria-label="Permalink to &quot;Debug symbols&quot;">​</a></h2><p><code>xclang_debug_symbols(&lt;target&gt;)</code> makes a program&#39;s debug symbols for its release after each of its links, with the toolchain&#39;s own tools:</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_executable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tool main.cpp)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_compile_options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tool </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -gline-tables-only)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">xclang_debug_symbols(tool)</span></span></code></pre></div><ul><li><code>tool.gsym</code> next to the program: functions, inlining and lines by address, about a tenth of the DWARF&#39;s size; <code>llvm-gsymutil tool.gsym --address=&lt;address&gt;</code> looks one up. llvm-gsymutil&#39;s warnings go to <code>tool.gsym.log</code>; <code>GSYM_ARGS --merged-functions</code> keeps every name of the functions identical code folding merged.</li><li><code>tool.dSYM</code> for a macOS target, made first, and the GSYM&#39;s source: dsymutil reads the objects the debug map points into, and the link keeps ThinLTO&#39;s for it in <code>&lt;build dir&gt;/tool.lto</code>.</li></ul><p>What GSYM and dSYM are for, and why they come from the link, is in <a href="./../features/debugging">debugging</a>.</p><h2 id="libclang" tabindex="-1">libclang <a class="header-anchor" href="#libclang" aria-label="Permalink to &quot;libclang&quot;">​</a></h2><p>A tool on libclang finds it with <code>find_package(Clang)</code>; see <a href="./../features/libclang#cmake">libclang</a>.</p><h2 id="the-thinlto-cache" tabindex="-1">The ThinLTO cache <a class="header-anchor" href="#the-thinlto-cache" aria-label="Permalink to &quot;The ThinLTO cache&quot;">​</a></h2><p>libclang is ThinLTO bitcode, so the link of a tool on it generates the code of every module the tool uses, which takes minutes. With <code>XCLANG_THINLTO_CACHE</code>, an absolute directory, a link after the first takes seconds:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DXCLANG_THINLTO_CACHE=/var/tmp/xclang-thinlto</span></span></code></pre></div><p><code>find_package(xclang)</code> makes the directory at configure time and adds the target&#39;s linker&#39;s flag to every link of the directory that called it and of its subdirectories: <code>-Wl,--thinlto-cache-dir=&lt;dir&gt;</code> for Linux and Windows targets, <code>-Wl,-cache_path_lto,&lt;dir&gt;</code> for macOS ones. The environment variable <code>XCLANG_THINLTO_CACHE</code> gives the first configure of every build tree its value. How the cache works, its pruning and why its path is fixed are in <a href="./../features/thinlto-cache">the ThinLTO cache</a>; keeping it in CI is in <a href="./ci">CI</a>.</p><h2 id="tested-by" tabindex="-1">Tested by <a class="header-anchor" href="#tested-by" aria-label="Permalink to &quot;Tested by&quot;">​</a></h2><p>tests/cmake builds with the package as above on every host, with CMake 3.28 and Ninja 1.11 and with the newest ones (cmake.yml): found by <code>PATH</code>, through the toolchain file for every other target the host can build, and downloaded by FetchContent from the release&#39;s tag. It links tests/libclang with the ThinLTO cache and again from it, and builds examples/cmake.</p>`,42)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
